     "共享单车已成为许多大城市日常生活的一部分。",
     "用一部手机，你就能解锁一辆单车，骑到地铁站，然后把它停在路边。",
     "这个简单的想法解决了车站与家之间的“最后一公里”问题。",
     "共享单车便宜、环保，而且有益健康。",
     "它们减少了交通拥堵，让空气更清洁。",
