    "text": "Many students stay up late playing games or watching shows, then feel sleepy in class the next day. Sleep is not a waste of time; it is when the body repairs itself and the brain organizes memories. Doctors recommend seven to nine hours of sleep for young adults. Going to bed and getting up at fixed times is more important than the total hours. A sudden change of schedule confuses the body clock, just like flying to another country. Before sleep, it helps to put the phone away, because the bright screen tricks the brain into staying awake. A cool, dark, and quiet bedroom also improves sleep quality. If you cannot fall asleep in twenty minutes, get up and read something boring until you feel sleepy. Good sleep improves memory, mood, and even the immune system. It is the cheapest health program in the world.",
