    "text": "Online shopping has become a daily habit for millions of people. With a few taps, goods arrive at your door within days, or even hours. The choices seem endless: clothes, food, books, and services all in one app. Prices are often lower than in physical shops because online stores save money on rent. However, convenient shopping brings new problems. Some people buy things they do not really need, influenced by live-stream sales and discounts. Packages pile up, and the plastic inside creates waste. Experts suggest making a list before shopping and waiting twenty-four hours before placing an order for anything expensive. Reading reviews carefully is another useful habit, since pictures can be misleading. Online shopping itself is neither good nor bad. What matters is whether we control our wallets, or our wallets are controlled by clever marketing.",
