    "text": "Many students like to study with music playing in the background. Does music really help? The answer depends on the task and the person. For repetitive work, such as copying notes or cleaning your desk, cheerful music can raise energy and make time pass faster. For deep reading or math problems, however, lyrics may compete with the words in the text and reduce understanding. That is why many learners prefer instrumental music or natural sounds like rain. Volume matters as well: soft background music is helpful, while loud music breaks concentration. Some researchers believe that the biggest benefit of music is not intelligence but emotion. A familiar song can calm nervous students before an exam and reduce anxiety. In short, music is a tool for study, not magic. Experiment a little, find what works for you, and then build your own study playlist.",
