     "好消息是，每个家庭都能在不怎么改变生活方式的情况下出一份力。",
     "一个滴水的龙头一年可能浪费数千升水，所以修好一个小漏洞就是一大节省。",
     "刷牙时关掉水龙头只需一秒钟，却能省下好几桶水。",
