    "text": "Moving to a new city is exciting, but it can also be lonely. Everything is unfamiliar: the streets, the food, and especially the people. Making new friends takes time, yet it is one of the most important skills for a happy life. The first step is to show up regularly. Join a club, a sports team, or a evening class, and go every week. Friendship grows from repeated meetings, not from one perfect conversation. The second step is to ask questions and really listen. People enjoy talking about their interests, and a good listener is always welcome. It also helps to accept invitations, even when you feel tired. A shared meal or a weekend walk can turn a stranger into a friend. Do not worry if things move slowly. Research says it takes dozens of hours to build a real friendship, so be patient and keep showing up.",
