    "text": "Millions of people share buses and subways every day, and small behaviors decide whether the journey is pleasant or painful. Basic etiquette is simple. Let passengers exit before entering; stand on the right side of escalators; keep phone calls short and quiet. Headphones are essential, because not everyone enjoys your playlist at eight in the morning. During rush hours, move to the center of the carriage so others can board. Offer seats to the elderly, pregnant women, and passengers with heavy bags, but do it naturally, without taking photos for social media. Eating strong-smelling food in a closed carriage is considered impolite in most cities. Rules differ slightly around the world: in Japan, phones are set to silent mode; in some European cities, tickets must be validated before boarding. The principle, however, is universal: public space belongs to everyone, so kindness and self-control keep it comfortable for all.",
