    "text": "For most students, money is limited, so learning to manage it is a life skill as important as any course. The first step is recording every expense for a month. Most people are surprised by the result: small daily purchases add up to a large sum. The second step is separating needs from wants. Food and textbooks are needs; the third pair of shoes is probably a want. Setting a weekly budget works better than a monthly one, because it is easier to control. Students can also use their biggest advantage: time and energy. Second-hand book markets, student discounts, shared memberships, and cooking with roommates cut costs without reducing the quality of life. Avoid consumer loans, which turn tomorrow's salary into today's shopping. Saving is not about being mean; it is about making choices. Money in a savings account is freedom: the freedom to say no, to change plans, and to face surprises calmly.",
