    "id": "k02",
    "title": "The Economics of Higher Education",
    "text": "Whether a university degree remains a sound investment has become one of the most contested questions in contemporary economics. For decades, graduates earned substantially more than non-graduates, and the wage premium appeared immune to economic cycles. Recently, however, the premium has stagnated in several developed economies while tuition has continued to climb, leaving many students indebted for decades. Critics argue that universities, protected by their reputations, have little incentive to control costs or to align curricula with labor market needs. Defenders counter that the degree still functions as a reliable signal of ability and perseverance, particularly in fields where skills are difficult to measure. The debate also obscures a more fundamental issue: education is both a private investment and a public good. A society benefits when its citizens think critically, tolerate difference, and participate in civic life, yet these returns never appear on an individual salary slip. Reducing higher education to a simple return-on-investment calculation, economists warn, may ultimately destroy the very qualities that justify the investment.",
