    "translations": [
     "大学学位是否仍是一项稳妥的投资，已成为当代经济学中争议最大的问题之一。",
     "几十年来，大学毕业生的收入远高于非毕业生，而且这一工资溢价似乎不受经济周期影响。",
     "然而近来，在若干发达经济体中，这一溢价已陷入停滞，而学费却持续攀升，使许多学生背负数十年的债务。",
     "批评者认为，大学受自身声誉庇护，几乎没有动力去控制成本，或使课程与劳动力市场需求相匹配。",
     "辩护者则反驳说，学位仍然是能力与毅力的可靠信号，在技能难以衡量的领域尤其如此。",
     "这场辩论还掩盖了一个更根本的问题：教育既是私人投资，也是公共产品。",
     "当公民具备批判性思维、包容差异并参与公共生活时，社会将从中受益，然而这些回报永远不会出现在个人的工资单上。",
     "经济学家警告说，将高等教育简化为简单的投资回报计算，最终可能会摧毁那些使这项投资正当化的品质本身。"
    ]
