    "id": "k03",
    "title": "Urbanization and Social Cohesion",
    "text": "Cities concentrate opportunity and inequality in the same streets, and whether urbanization strengthens or weakens social cohesion depends largely on design. Dense neighborhoods facilitate chance encounters, which sociologists regard as the raw material of trust. Yet density without thoughtful planning produces congestion, anonymity, and segregation instead. When affordable housing is pushed to the urban periphery, low-income workers spend hours commuting, effectively excluding them from the cultural and professional life of the center. Mixed-use development offers a partial remedy: residential blocks combined with workplaces, schools, and public space encourage residents of different backgrounds to share daily routines. Public transport functions as a social equalizer precisely because people of every class sit in the same carriages. Some scholars caution, however, that physical proximity alone does not generate community;shared institutions such as libraries, parks, and markets convert geographic closeness into genuine social bonds. The challenge for rapidly urbanizing societies is therefore not merely to build more cities, but to build cities worth belonging to.",
