    "translations": [
     "城市将机遇与不平等集中在同样的街道上，而城市化是增强还是削弱社会凝聚力，很大程度上取决于设计。",
     "密集的社区促进了偶遇，社会学家将其视为信任的原材料。",
     "然而，缺乏深思熟虑规划的密度反而会带来拥堵、匿名性和隔离。",
     "当经济适用房被推到城市边缘时，低收入工人要花数小时通勤，实际上将他们排除在中心的文化和职业生活之外。",
     "混合用途开发提供了部分解决方案：住宅区与工作场所、学校和公共空间相结合，鼓励不同背景的居民共享日常生活。",
     "公共交通之所以能起到社会均衡器的作用，正是因为各个阶层的人都坐在同样的车厢里。",
     "然而，一些学者警告说，仅凭物理上的邻近并不能产生共同体；图书馆、公园和市场等共享机构才能将地理上的接近转化为真正的社会纽带。",
     "因此，快速城市化社会面临的挑战不仅仅是建造更多城市，而是建造值得归属的城市。"
    ]
