    "id": "k04",
    "title": "The Ethics of Gene Editing",
    "text": "The advent of CRISPR technology has transformed gene editing from a distant possibility into a practical, inexpensive tool, and with that transformation comes an urgent ethical question: just because we can edit the human genome, should we? Proponents emphasize the therapeutic potential. Diseases such as sickle cell anemia, which once condemned patients to lifelong suffering, can now plausibly be corrected at their genetic source. Opponents raise three distinct objections. First, safety: editing errors may introduce mutations that propagate through future generations. Second, consent: an embryo cannot agree to having its DNA rewritten. Third, justice: if wealthy families purchase genetic advantages for their children, edited traits could harden existing class divisions into biology itself. Many bioethicists therefore distinguish sharply between somatic editing, which treats an individual patient, and germline editing, which alters inherited DNA. The former commands broad support; the latter remains internationally contentious. The lesson of this debate extends beyond genetics. Scientific capability, philosophers remind us, defines what is possible, never what is permissible.",
