    "translations": [
     "CRISPR技术的出现已将基因编辑从遥远的可能性转变为实用且廉价的工具，而伴随这一转变而来的是一个紧迫的伦理问题：仅仅因为我们能够编辑人类基因组，我们就应该这样做吗？",
     "支持者强调其治疗潜力。",
     "镰状细胞贫血等疾病曾使患者终生饱受折磨，如今已有望从基因根源上得到矫正。",
     "反对者提出了三点不同的异议。",
     "第一，安全性：编辑错误可能引入会传递给后代的突变。",
     "第二，知情同意：胚胎无法同意自己的DNA被改写。",
     "第三，正义问题：如果富裕家庭为子女购买基因优势，经过编辑的性状可能将现有的阶级分化固化为生物学本身。",
     "因此，许多生物伦理学家严格区分体细胞编辑与生殖系编辑，前者治疗个体患者，后者改变可遗传的DNA。",
     "前者获得广泛支持；后者在国际上仍存争议。",
     "这场辩论的教训超越了遗传学领域。",
     "哲学家提醒我们，科学能力界定的是什么是可能的，而绝非什么是被允许的。"
    ]
