    "id": "k05",
    "title": "The Attention Economy and the Decline of Deep Reading",
    "text": "Digital platforms do not sell content; they sell attention, and the consequences of that business model are only beginning to be understood. Advertisers pay for engagement, so algorithms optimize for whatever keeps eyes on the screen, and outrage, novelty, and conflict reliably outperform nuance. Meanwhile, the long-form reading that once structured public discourse demands sustained concentration, an increasingly scarce resource. Scholars of literacy note that deep reading is not an innate ability but a cultivated skill, built through practice and reinforced by cultural expectations. When skimming replaces immersion, the capacity to follow extended arguments may atrophy, and with it a certain kind of democratic citizenship that depends on evaluating evidence rather than reacting to headlines. Critics of this view object that every new medium, from the novel to television, provoked identical anxieties, and society adapted each time. Yet two features distinguish the present moment: the personalization of feeds, which fragments shared experience, and the commercial incentive to engineer distraction deliberately. What is at stake is not literacy itself, but the quality of thought that literacy makes possible.",
