    "translations": [
     "数字平台出售的不是内容，而是注意力，而这种商业模式的后果才刚刚开始被人们所理解。",
     "广告商为互动付费，因此算法会优化一切能让目光停留在屏幕上的内容，而愤怒、新奇和冲突往往比细腻微妙更能胜出。",
     "与此同时，曾一度构建公共话语的长篇阅读需要持续的专注力，而这是一种日益稀缺的资源。",
     "研究读写能力的学者指出，深度阅读并非一种与生俱来的能力，而是一种后天培养的技能，它通过练习得以建立，并由文化期待加以强化。",
     "当略读取代了沉浸式阅读，追随长篇论证的能力可能会退化，而某种依赖评估证据而非对标题作出反应的民主公民素养也会随之衰退。",
     "对这一观点的批评者反驳说，每一种新媒介——从小说到电视——都曾引发过同样的焦虑，而社会每次都适应了过来。",
     "然而，当下有两个特征使其与众不同：信息流的个性化，它使共享经验变得碎片化；以及刻意制造分心的商业动机。",
     "真正受到威胁的并非读写能力本身，而是读写能力所促成的思维质量。"
    ]
