    "id": "k06",
    "title": "Climate Policy and the Economics of Carbon Pricing",
    "text": "Climate change presents what economists describe as the largest market failure in history: the costs of carbon emissions are borne by everyone, while the benefits of emitting accrue to the few. Carbon pricing attempts to correct this failure by making polluters pay, either through a direct tax or through cap-and-trade systems that let the market discover the price of emissions. The theoretical appeal is elegance. Once pollution carries a cost, firms innovate to avoid it, consumers shift toward cleaner products, and governments collect revenue that can offset the burden on households. Empirical evidence partially supports this logic; British Columbia's carbon tax, for instance, reduced fuel use without measurable damage to its economy. Yet obstacles remain formidable. Pricing carbon unilaterally risks pushing production to countries with laxer rules, a phenomenon known as carbon leakage. And because the atmosphere is indifferent to national borders, coordination problems that plague every international treaty reappear here with unusual force. The question is no longer whether carbon should be priced, but whether political systems can sustain a price high enough, long enough, to matter.",
