     "一旦污染有了代价，企业就会创新以规避它，消费者会转向更清洁的产品，政府则能征收收入来抵消家庭的负担。",
     "实证证据部分支持这一逻辑；例如，不列颠哥伦比亚省的碳税减少了燃料使用，却没有对其经济造成可衡量的损害。",
     "然而障碍依然巨大。",
