    "title": "Automation and the Widening of Income Inequality",
    "text": "Income inequality has widened across most developed economies for four decades, and automation is increasingly identified as a central cause rather than a background condition. The mechanism operates through what economists call skill-biased technical change: machines substitute for routine work, whether manual or clerical, while complementing the analytical and creative tasks performed by highly educated workers. The middle of the wage distribution consequently hollows out, employment polarizes into high-paid professionals and low-paid service jobs, and labor's share of national income declines relative to capital's. Technology, however, is not destiny. Institutions mediate how automation's gains are distributed: Scandinavian countries have absorbed comparable technological change with far less inequality, thanks to strong collective bargaining, generous retraining, and wage compression. Corporate governance matters as well, since shareholder pressure encourages firms to automate aggressively and redistribute the savings upward. Historians add a final caution. In the nineteenth century, the gains of mechanization took decades to reach ordinary workers, and the interval was filled with social upheaval. Whether this transition can be compressed into something gentler remains an open and urgent question.",
