    "translations": [
     "基于应用程序的工作创造了数百万个灵活就业岗位，并由此引发了一个根本性的法律问题：零工工作者是雇员还是独立承包商？",
     "这一区别至关重要。",
     "员工享有最低工资、社会保险和集体谈判权；而承包商原则上享有自由并自行承担风险。",
     "平台坚称其劳动者是企业家，可以自行选择何时工作以及是否工作。",
     "法院和监管机构越来越不认同这一说法，指出算法设定价格、分配任务并有效监督绩效，这更像管理而非市场化的独立自主。",
     "这场争议背后的经济逻辑比这些应用程序更为古老。",
     "企业一直有动机将固定的劳动力成本转化为可变成本，而数字技术只是让这种做法得以规模化。",
     "改革方案大致分为三大阵营：将零工劳动者重新归类为正式员工，设立享有部分福利的中间类别，或者使福利可携带并附着于个人而非工作岗位。",
     "每种方案都以不同方式重新分配风险，且每种方案都引发了政治摩擦。",
     "大多数学者一致认为，不再站得住脚的是现状——劳动者承担灵活性的成本，而平台攫取其利润。"
    ]
