    "title": "Misinformation and the Fragility of Shared Truth",
    "text": "Every society depends on a roughly shared picture of reality, and that picture is under unprecedented strain. Misinformation is not new; rumors, propaganda, and urban legends have always circulated. What has changed is the infrastructure of distribution. Social media removes the editorial filters that once slowed falsehood, and engagement-driven algorithms amplify whatever provokes the strongest reaction, which is rarely the most accurate content. Research on information cascades shows that false news spreads significantly faster and farther than true news, largely because novelty and outrage travel better than correction. The deeper damage, however, may be epistemic rather than factual. When citizens can no longer agree on basic facts, trust in institutions erodes across the board, and every disputed claim becomes just another opinion. Countermeasures exist but each has costs. Fact-checking reaches too few people and arrives too late; platform moderation raises legitimate fears of censorship; media literacy education works slowly and unevenly. Some political scientists conclude that the problem is not solvable by technology alone, because its roots lie in polarization: people share falsehoods not because they cannot distinguish truth, but because the falsehood expresses loyalty to their group.",
