    "title": "Aging Societies and the Arithmetic of Pensions",
    "text": "Population aging is often described as a triumph of public health, and it is; it is also an unfolding fiscal problem with no comfortable solution. The arithmetic is unforgiving. Pay-as-you-go pension systems assume a stable ratio of workers to retirees, but as fertility falls and longevity rises, that ratio deteriorates steadily across the developed world and increasingly in developing economies. Fewer contributors support more beneficiaries for longer periods, and the gap must be closed by some combination of higher taxes, later retirement, or reduced benefits, each politically painful. Extending working lives is the most commonly prescribed remedy, and it has genuine merit: healthy older adults represent an underused reservoir of experience. Yet age discrimination in hiring remains pervasive, and physical labor cannot be performed indefinitely regardless of pension law. Some economists look to productivity growth as the escape route, hoping that each worker of the future will generate enough surplus to support more retirees. Optimists note that forecasts have repeatedly underestimated both health and productivity; pessimists reply that immigration, the other demographic escape valve, has become politically toxic in many countries. What is certain is that doing nothing is itself a decision, and the most expensive one available.",
