    "title": "The Trouble with Measuring Intelligence",
    "text": "The dream of measuring intelligence with a single number has shaped education, employment, and immigration policy for over a century, and the dream has always been controversial. Early intelligence tests were built on plausible assumptions: that cognitive ability is stable within a person, comparable across people, and largely independent of culture. Each assumption has since been challenged. Test scores predict school performance, critics concede, but schooling itself trains the abilities the tests measure, so the prediction is partly circular. Cultural bias has proven harder to eliminate than early psychometricians hoped; a question about orchestras or rowing measures exposure as much as aptitude. The most persistent controversy concerns heredity. Twin studies suggest that genetic factors explain a substantial share of variation in test scores, yet heritability says nothing about modifiability, and average scores have risen dramatically across generations, far too fast for genetics to explain. Modern researchers have largely abandoned the search for a single essence of intelligence in favor of multidimensional models that distinguish fluid reasoning, accumulated knowledge, and domain-specific skills. What the century-long debate ultimately reveals is a lesson about measurement itself: quantifying something does not make it simple, and the map we draw of the mind reflects the tools as much as the territory.",
