    "translations": [
     "疫情将远程办公从一种边缘特权转变为主流期望，而它所引发的重组，可能比催生它的这场危机更为持久。",
     "对员工而言，好处是实实在在的：省下的通勤时间、地理上的自由，以及对工作日更大的自主权。",
     "对雇主而言，这笔账就没那么清楚了。",
     "办公地产成本高昂，而当地理位置不再重要时，全球人才库也随之扩大；然而管理者们担心如何指导初级员工、如何保存机构知识，以及如何维系那些激发创新的非正式交流。",
     "迄今为止的证据呈现出一种因情况而异的图景。",
     "完全远程的安排适合成熟、界定清晰的个人工作，而混合模式尽管在排期上颇为麻烦，似乎却能兼得两者的优势。",
     "组织学者强调，远程办公不仅仅是地点的改变，更是管理理念的改变：当出勤不再能作为勤勉的替代指标时，就必须直接衡量成果，而有些管理者从未学会这样做。",
     "城市同样也在重新调整。",
     "市中心人流量的下降威胁着公共交通系统和小企业，促使城市规划者设想将办公区改造成混合居住社区。",
     "办公室并没有消亡，但它对工作的垄断已被打破，没有人指望这种垄断会回归。"
    ]
