    "id": "k16",
    "title": "Pricing Nature: Biodiversity in Economic Terms",
    "text": "Ecosystems deliver services that markets have traditionally priced at zero: forests regulate water cycles, wetlands purify pollution, pollinators sustain agriculture, and oceans absorb carbon and heat. Because no invoice arrives for these services, conventional accounting treats them as free, and the predictable result is overuse. Biodiversity loss, ecologists warn, is the systemic consequence: species extinction now proceeds at rates far exceeding the geological background, and each loss removes a component whose function may not be replaceable. Economists have responded with the language of natural capital, assigning monetary value to ecosystem services so that destruction shows up on the balance sheet. The approach has scored practical victories; payments for watershed protection, for instance, have financed reforestation that benefits both downstream cities and upstream farmers. Yet the valuation paradigm provokes philosophical resistance. Assigning a price to a species, critics argue, implies that it can be traded off against money, whereas many people regard extinction as a moral wrong regardless of cost. There is also a technical objection: ecosystems are complex systems with tipping points, and linear pricing systematically underestimates the value of keeping them away from collapse. Whether economic instruments can be made humble enough to serve ecology, rather than to govern it, may determine how much of the living world the next century inherits.",
