    "translations": [
     "生态系统提供的服务，市场历来定价为零：森林调节水循环，湿地净化污染，传粉者维系农业，海洋吸收碳和热量。",
     "由于这些服务不会送来账单，传统会计将它们视为免费，可预见的结果就是过度使用。",
     "生态学家警告说，生物多样性丧失是系统性后果：物种灭绝的速度如今远超地质背景速率，而每一次丧失都移除一个其功能可能无法替代的组成部分。",
     "经济学家以自然资本的语言作出回应，为生态系统服务赋予货币价值，使破坏行为体现在资产负债表上。",
     "这一方法已取得实际成果；例如，流域保护付费已为植树造林提供资金，使下游城市和上游农民双双受益。",
     "然而，这种估值范式引发了哲学上的抵制。",
     "批评者认为，为物种定价意味着它可以与金钱进行权衡取舍，而许多人则认为无论代价如何，灭绝都是一种道德上的错误。",
     "还有一个技术上的反对意见：生态系统是复杂系统，存在临界点，而线性定价会系统性地低估使其免于崩溃的价值。",
     "经济工具能否变得足够谦卑，以服务于生态而非支配生态，这可能决定下个世纪能继承多少生命世界。"
    ]
