    "translations": [
     "古典经济学假定选择越多消费者越受益，但大量研究表明，过多的选择可能既损害决策质量，也损害幸福感。",
     "在颇具影响力的实验中，面对琳琅满目的果酱或巧克力选择的购物者，比那些只面对有限选择的购物者更不可能买下任何东西；而想象自己拥有最大化选择的参与者，比那些满足于足够好的人报告了更多的后悔与反复纠结。",
     "所提出的机制合乎直觉。",
     "每一个被放弃的选项都伴随着心理代价；比较各种备选方案在认知上是昂贵的；而当结果令人失望时，丰富的选择又为自责提供了新的靶子，因为面对如此多的可能性，糟糕的结果必定是自己的过错。",
     "批评者质疑原始发现的稳健性，指出重复实验的结果参差不齐，且该效应在很大程度上取决于情境、专业知识和文化。",
     "然而，即便是弱化后的版本也仍有分量。",
     "选择架构，即选项的设计，已成为一个正当的研究领域：退休计划的成败部分取决于其默认设置，而流媒体服务则发现精心策划的列表比无穷无尽的目录效果更好。",
     "选择悖论经批评者修正后，依然作为一种警示而存在，提醒人们不要信奉一种简单的意识形态：即自由是以选项的数量来衡量，而非以这些选项所造就的生活质量来衡量。"
    ]
