    "id": "k20",
    "title": "Memory, Learning, and the Science of Forgetting",
    "text": "Intuition treats forgetting as failure, but cognitive science regards it as a feature of an efficient system: a brain that retained everything would drown in trivia, so it keeps what is retrieved and discards what is not. This insight, strange as it sounds, supplies the practical foundation for effective learning. Testing oneself, for example, does not merely assess knowledge; it strengthens it, because the act of retrieval consolidates the trace. Students who quiz themselves consistently outperform those who reread, even though rereading feels more productive, an illusion generated by the ease of processing rather than by learning itself. Timing matters equally. Reviews spaced across days combat the forgetting curve far better than massed practice, a result so reliable that it has been replicated for over a century yet remains absent from most study habits. Emotional state modulates memory as well: stress hormones enhance consolidation of threatening events while impairing the calm retrieval that examinations demand. Educators increasingly argue that teaching should be designed around these regularities, embedding low-stakes quizzes and cumulative review into curricula. The deeper lesson is philosophical. Memory is not a recording to be consulted but a reconstruction rebuilt at each recall, shaped by use; we remember, quite literally, what we practice remembering.",
