    "id": "k23",
    "title": "The Politics of the Energy Transition",
    "text": "The technical case for renewable energy has essentially been won; the political case is still being argued. Solar and wind are now the cheapest sources of new electricity across most of the world, and storage costs continue their steep decline, yet the transition from fossil fuels proceeds unevenly because it redistributes not just energy but power, income, and identity. Regions built on coal or oil face the erosion of their economic base, and workers with decades of specialized experience are asked to retrain for jobs that may exist elsewhere. Energy scholars describe the resulting resistance as rational rather than irrational: people defend not only wages but status, community, and a way of life. Transitions succeed, historical evidence suggests, when the costs are visibly shared and the benefits locally received, which explains why compensations attached to place outperform compensation attached to individuals. Internationally, the geometry is harder still. Developing economies are asked to forgo the carbon-intensive path that rich countries climbed, while perceiving little of the historical responsibility for atmospheric carbon. Climate finance, technology transfer, and green industrial policy are the instruments being tested. The transition, in the end, is not an engineering project with political obstacles; it is a political project whose engineering, fortunately, already works.",
