    "translations": [
     "为什么有些社区能从灾难中迅速恢复，而另一些面临同样损失的社区却多年萎靡不振？",
     "地震和洪水之后的研究一再指向工程报告中缺失的一个变量：社会资本，即连接居民的关系网络和互惠规范。",
     "在人们彼此相识的社区，疏散更有秩序，信息共享更快，重建中的欺诈更少；公共卫生研究得出了相似的结论，发现相互联系的社区即使在控制收入因素后，死亡率也更低。",
     "这一概念由社会学家提出，并经政治学家推广，它区分了纽带资本——相似群体内部的紧密联系——与桥梁资本——跨越社会边界的较弱联系。",
     "两者都很重要，但方式不同：纽带关系在危机中提供支持，而桥梁关系则提供通往自身圈子之外的机会和信息。",
     "这些政策影响让技术官僚们感到不安。",
     "基础设施项目通常以钢铁和混凝土来衡量，然而一条切断社区步行路线的道路可能摧毁的福祉多于它所创造的，而一个将既有社区打散的安置方案可能瓦解数十年积累的信任。",
     "衡量此类损失并不精确，而这恰恰是它们常常被忽视的原因。",
     "社会资本如同其金融同名物一样，是一种越用越增值、越忽视越消失的资产。"
    ]
