    "translations": [
     "标准化考试体现了精英统治核心处的一种张力：使考试在一种意义上公平的那些特征，恰恰使它在另一种意义上不公平。",
     "标准化确保每位考生在相同条件下面对相同的题目，使评估免受曾腐蚀旧有庇护与推荐制度的偏袒和主观性的影响。",
     "然而，对准备程度不平等的考生给予同等对待，反而复制了它声称要超越的不平等，因为获得辅导、安静的学习空间和应试文化的机会因家庭背景而差异巨大。",
     "近期研究加剧了这一批评：分数与家庭收入相关，辅导能够显著提高成绩，尽管关于效应大小的争论仍在持续。",
     "支持者回应称，其他替代方案更糟。",
     "他们指出，整体性招生反而更加不透明，而非更透明；主观评估在历史上一直以更难察觉和纠正的方式偏袒特权阶层；而分数本身在不同学校之间也存在不均衡的注水现象。",
     "几所曾放弃考试要求的大学后来恢复了这些要求，并报告称，分数有助于识别那些来自资源匮乏学校、成绩单几乎说明不了什么的优秀学生。",
     "正在形成的共识既不支持废除考试，也不推崇考试崇拜，而是主张校准：将考试视为若干信号之一，在权衡时意识到它们能衡量什么——准备程度、应试技巧和已发展的能力——以及它们不能衡量什么：品格、创造力或成长潜力。",
     "评估如同任何工具，其公正程度取决于解读它的制度。"
    ]
