    "id": "k26",
    "title": "Machine Translation and the Fate of Language Diversity",
    "text": "Machine translation has crossed a threshold: for major languages, instant, inexpensive, and mostly reliable translation is now an everyday utility. The consequences for human translation, for language learning, and for linguistic diversity are still unfolding, and not all of them are welcome. Optimists foresee a world in which language barriers cease to matter, in which a farmer consults agricultural research from another continent and a patient understands a foreign diagnosis. Pessimists reply that convenience selects against effort: if translation is free, the incentive to learn second languages weakens, and with language learning goes much of the cultural fluency that machines, whatever their fluency, do not possess. The deeper threat concerns minor languages. Neural systems require vast training corpora, which exist only for languages with extensive written records; languages spoken by small communities without such records are effectively invisible to the technology, and the digital prominence of a dozen languages may accelerate the decline of thousands. Some linguists detect a paradox at the center: the same internet that endangers small languages also enables their documentation, and communities increasingly use recording technology, keyboards, and even machine translation trained on rescued corpora to revitalize their speech. Technology, as usual, is not the verdict; it is the terrain on which choices about value are contested.",
