     "机器翻译已经跨过了一个门槛：对于主要语言而言，即时、廉价且大体可靠的翻译如今已成为日常实用工具。",
     "这对人工翻译、语言学习以及语言多样性的影响仍在显现，而且并非所有影响都是受欢迎的。",
     "乐观者预见了一个语言障碍不再重要的世界：农民可以查阅另一个大陆的农业研究，患者也能理解外国的诊断。",
     "悲观者回应说，便利会挤压努力：如果翻译是免费的，学习第二语言的动力就会减弱，而随着语言学习的消退，机器所不具备的那种文化流利度也会大量丧失，无论机器多么流利。",
     "更深层的威胁涉及小众语言。",
     "神经系统的训练需要海量语料，而这些语料只存在于拥有大量书面记录的语言中；没有此类记录的小型社群所说的语言，对这项技术而言实际上是不可见的，而十几种语言在数字领域的突出地位，可能会加速数千种语言的衰落。",
