    "title": "Programming Morality: The Ethics of Autonomous Vehicles",
    "text": "Autonomous vehicles promise to eliminate the human error responsible for the overwhelming majority of traffic deaths, and they may eventually fulfill that promise. Before they do, they must answer a question human drivers never had to formalize: when a collision is unavoidable, whom should the machine protect? Philosophers have long explored such dilemmas in thought experiments, and public surveys reveal a striking inconsistency. Respondents approve of vehicles programmed to minimize total casualties, yet admit they would prefer to buy cars that protect their own occupants first; a utilitarian fleet, several studies conclude, might be commercially unsellable. Engineers object that the framing is misleading. Real collisions offer no tidy trolley problems, only probabilities under uncertainty, and the genuinely hard questions are less cinematic: how cautious should an algorithm be around children near the roadside, how should it weigh rare catastrophic failures against frequent minor ones, and who bears liability when the machine errs? Legal systems are improvising answers, gradually shifting responsibility from drivers toward manufacturers and software, a shift with profound implications for insurance and innovation incentives. The episode carries a wider lesson. Automated systems do not remove moral judgment from the world; they relocate it, from the moment of crisis to the design document, where decisions are made once, in advance, and without anyone watching.",
