    "id": "k30",
    "title": "The Future of the Book",
    "text": "Predictions of the book's death have accompanied every new medium, and the book has survived them all by changing what it is. The codex outlasted the scroll because it was superior technology: random access, portability, and capacity for annotation. Print standardized texts and created the public sphere; the paperback democratized it; the e-book promised to complete the democratization, and in markets with weak distribution it partly has. Yet in mature markets, physical books have refused to disappear, and sales have even recovered. The explanation emerging from reading research and publishing economics is that formats serve different functions. Screens excel at search, portability, and volume, which suits reference and serial entertainment; paper suits sustained, linear attention, and readers repeatedly report, and eye-tracking studies partly confirm, deeper comprehension on the page. Meanwhile the book's social role has inverted. Digital distribution vastly expanded what can be published, while self-publishing dismantled the gatekeeping that once filtered quality, with results that readers experience as both abundance and flood. Curation has consequently migrated from publishers to communities, algorithms, and trusted individuals. The book of the future may therefore be less a container than a claim: a text that some person or community has judged worth the sustained attention that only books command. By that standard, the book is not dying; it is being redefined as exactly what cannot be skimmed.",
